<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import ConfirmationModal from '@/Components/ConfirmationModal.vue'; import InputError from '@/Components/InputError.vue'; import ValidationSummary from '@/Components/ValidationSummary.vue'; import {Head,useForm,router} from '@inertiajs/vue3'; import {reactive, ref} from 'vue';
const props=defineProps<{payments:any[];summary:any;customers:any[];events:any[];packages:any[];filters:any}>(); const filters=reactive({...props.filters}); const apply=()=>router.get(route('admin.payments.index'),filters,{preserveState:true,replace:true}); const reset=()=>{filters.search='';filters.status='';filters.customer_id='';apply()}; const form=useForm({customer_id:'',event_id:'',event_package_id:'',original_amount:'',discount:0,paid_amount:0,payment_method:'cash',reference:'',payment_date:''}); const pendingPayment=ref<any>(null); const confirmPayment=()=>router.patch(route('admin.payments.confirm',pendingPayment.value.id),{}, {onFinish:()=>pendingPayment.value=null}); const money=(value:any)=>`$${Number(value || 0).toFixed(2)}`; const remaining=(payment:any)=>Math.max(Number(payment.final_amount)-Number(payment.paid_amount),0);
</script>
<template><Head title="Manual payments"/><AuthenticatedLayout><template #header><h2 class="text-xl font-semibold">Manual payments</h2></template><div class="mx-auto max-w-7xl space-y-5 p-6"><section class="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><div class="rounded bg-white p-4 shadow"><p class="text-sm text-gray-500">Total final amounts</p><p class="text-xl font-semibold">{{money(summary.total_final_amount)}}</p></div><div class="rounded bg-white p-4 shadow"><p class="text-sm text-gray-500">Total paid</p><p class="text-xl font-semibold">{{money(summary.total_paid_amount)}}</p></div><div class="rounded bg-white p-4 shadow"><p class="text-sm text-gray-500">Total remaining</p><p class="text-xl font-semibold">{{money(summary.total_remaining_amount)}}</p></div><div class="rounded bg-white p-4 shadow"><p class="text-sm text-gray-500">Pending payments</p><p class="text-xl font-semibold">{{summary.pending_count}}</p></div><div class="rounded bg-white p-4 shadow"><p class="text-sm text-gray-500">Confirmed payments</p><p class="text-xl font-semibold">{{summary.confirmed_count}}</p></div></section><form @submit.prevent="form.post(route('admin.payments.store'))" class="grid gap-2 bg-white p-4 shadow sm:grid-cols-4"><div><select v-model="form.customer_id" required class="w-full rounded border-gray-300"><option value="">Customer</option><option v-for="c in customers" :value="c.id">{{c.name}}</option></select><InputError :message="form.errors.customer_id" class="mt-1"/></div><div><select v-model="form.event_id" class="w-full rounded border-gray-300"><option value="">No event</option><option v-for="e in events" :value="e.id">{{e.title}}</option></select><InputError :message="form.errors.event_id" class="mt-1"/></div><div><input v-model="form.original_amount" type="number" placeholder="Original amount" required class="w-full rounded border-gray-300"><InputError :message="form.errors.original_amount" class="mt-1"/></div><div><input v-model="form.paid_amount" type="number" placeholder="Paid amount" class="w-full rounded border-gray-300"><InputError :message="form.errors.paid_amount" class="mt-1"/></div><button class="rounded bg-indigo-600 p-2 text-white">Record payment</button><div class="sm:col-span-4"><ValidationSummary :errors="form.errors"/></div></form><form @submit.prevent="apply" class="flex flex-wrap gap-2"><input v-model="filters.search" placeholder="Search customer, event, reference" class="rounded border-gray-300"><select v-model="filters.status" class="rounded border-gray-300"><option value="">All statuses</option><option value="pending">Pending</option><option value="confirmed">Confirmed</option><option value="cancelled">Cancelled</option><option value="refunded">Refunded</option></select><select v-model="filters.customer_id" class="rounded border-gray-300"><option value="">All customers</option><option v-for="customer in customers" :value="customer.id">{{customer.name}}</option></select><button class="rounded bg-gray-800 px-3 text-white">Search</button><button type="button" @click="reset" class="text-gray-600">Reset</button></form><div class="overflow-x-auto bg-white shadow"><table class="min-w-full text-left text-sm"><thead class="bg-gray-50 text-gray-600"><tr><th class="p-3">Customer</th><th class="p-3">Event</th><th class="p-3">Package</th><th class="p-3">Original</th><th class="p-3">Discount</th><th class="p-3">Final</th><th class="p-3">Paid</th><th class="p-3">Remaining</th><th class="p-3">Status</th><th class="p-3">Date / Reference</th><th class="p-3"></th></tr></thead><tbody><tr v-for="payment in payments" :key="payment.id" class="border-t"><td class="p-3">{{payment.customer?.name}}</td><td class="p-3">{{payment.event?.title || 'Not provided'}}</td><td class="p-3">{{payment.package?.name || 'Not provided'}}</td><td class="p-3">{{money(payment.original_amount)}}</td><td class="p-3">{{money(payment.discount)}}</td><td class="p-3">{{money(payment.final_amount)}}</td><td class="p-3">{{money(payment.paid_amount)}}</td><td class="p-3">{{money(remaining(payment))}}</td><td class="p-3 capitalize">{{payment.status}}</td><td class="p-3">{{payment.payment_date || 'No date'}}<br><span class="text-gray-500">{{payment.reference || 'No reference'}}</span></td><td class="p-3"><button v-if="payment.status==='pending'" @click="pendingPayment=payment" class="rounded bg-green-600 px-2 py-1 text-white">Confirm</button></td></tr></tbody></table><p v-if="!payments.length" class="p-4 text-gray-600">No payments match your search or filters.</p></div></div><ConfirmationModal :show="!!pendingPayment" title="Confirm payment?" message="This will mark the manual payment as confirmed." confirm-label="Confirm payment" @close="pendingPayment=null" @confirm="confirmPayment"/></AuthenticatedLayout></template>
